import numpy as np
from PIL import Image
a = np.array(Image.open('first_frame.png')).astype(int)
h,w,_ = a.shape
R,G,B = a[...,0],a[...,1],a[...,2]

# check the 'W' strip near x114-116 y44-57
print(\"strip x112-118 y44-57:\")
for y in range(44,58):
    print(y, [tuple(a[y,x]) for x in range(111,120)])

# Connected components for several thresholds
def comps(mask,minarea=15):
    seen=np.zeros_like(mask,bool); out=[]
    for y in range(h):
        for x in range(w):
            if mask[y,x] and not seen[y,x]:
                stack=[(y,x)];seen[y,x]=1;pts=[]
                while stack:
                    cy,cx=stack.pop();pts.append((cy,cx))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=cy+dy,cx+dx
                            if 0<=ny<h and 0<=nx<w and mask[ny,nx] and not seen[ny,nx]:
                                seen[ny,nx]=1;stack.append((ny,nx))
                if len(pts)>=minarea:
                    ys=[p[0] for p in pts];xs=[p[1] for p in pts]
                    out.append((len(pts),min(xs),min(ys),max(xs),max(ys)))
    return sorted(out,key=lambda c:(c[2],c[1]))

print(\"\\n# r<45 components:\")
for c in comps((R<45)&(G<45)&(B<45)): print(c)
